namespace ghidra.app.plugin.core.decompiler.taint;

using ghidra.app.decompiler;
using ghidra.app.plugin.core.decompiler.taint.TaintState;
using ghidra.program.model.address;
using ghidra.program.model.pcode;

public class TaintLabel {

	private MarkType mtype;
	private ClangToken token;

	private string fname;
	private HighFunction hfun;
	private HighVariable hvar;
	private Varnode vnode;
	private Address vnAddr;
	private bool active;
	private string label;
	private bool isGlobal = false;
	private bool bySymbol = false;

	// TODO: This is not a good identifier since it could change during re work!
	private Address addr;
	private ClangLine clangLine;
	private int size = 0;

	public TaintLabel(MarkType mtype, ClangToken token)
    {

		HighVariable highVar = token.getHighVariable();
		if (highVar == null) {
			hfun = token.getClangFunction().getHighFunction();
		}
		else {
			hfun = highVar.getHighFunction();
			HighSymbol symbol = highVar.getSymbol();
			if (symbol != null) {
				isGlobal = symbol.isGlobal();
			}
		}

		this.vnode = token.getVarnode();

		string fn = token is ClangFuncNameToken ftoken ? ftoken.getText()
				: hfun.getFunction().getName();
		PcodeOp pcodeOp = token.getPcodeOp();
		Address target =
			pcodeOp == null ? hfun.getFunction().getEntryPoint() : pcodeOp.getSeqnum().getTarget();
		if (vnode == null && pcodeOp != null) {
			vnode = pcodeOp.getOutput();
		}

		if (vnode != null) {
			vnAddr = vnode.getAddress();
			HighVariable high = vnode.getHigh();
			if (high is HighLocal) {
				highVar = hfun.splitOutMergeGroup(high, vnode);
			}
		}

		this.mtype = mtype;
		this.token = token;
		this.fname = fn;
		this.hvar = highVar;
		this.active = true;
		this.addr = target;
		if (hvar != null) {
			size = hvar.getSize();
		}
		this.clangLine = token.getLineParent();

		// Initial label is one of SOURCE, SINK, or GATE
		this.label = mtype.toString();
	}

	public TaintLabel(MarkType mtype, ClangToken token, HighVariable hvar,
			string fn, Address target) {

		this.mtype = mtype;
		this.token = token;
		if (token != null) {
			this.clangLine = token.getLineParent();
		}
		this.hvar = hvar;
		if (hvar == null) {
			if (token != null) {
				hfun = token.getClangFunction().getHighFunction();
			}
		}
		else {
			size = hvar.getSize();
			hfun = hvar.getHighFunction();
			HighSymbol symbol = hvar.getSymbol();
			if (symbol != null) {
				isGlobal = symbol.isGlobal();
			}
		}
		this.fname = fn;
		this.addr = target;
		active = true;

		// Initial label is one of SOURCE, SINK, or GATE
		label = mtype.toString();
	}

	public TaintLabel(MarkType mtype, string fn, Address target, Address refAddress) : this(mtype, null, null, fn, target)
    {
		vnAddr = refAddress;
	}

	public ClangLine getClangLine() {
		return this.clangLine;
	}

	public void setClangLine(ClangLine clangLine) {
		this.clangLine = clangLine;
	}

	public void setLabel(string label) {
		this.label = label;
	}

	public string getLabel() {
		return label;
	}

	public MarkType getType() {
		return this.mtype;
	}

	public ClangToken getToken() {
		return this.token;
	}

	public HighFunction getHighFunction() {
		return this.hfun;
	}

	public string getFunctionName() {
		return this.fname;
	}

	public HighVariable getHighVariable() {
		return this.hvar;
	}

	public Address getAddress() {
		return addr;
	}

	/* @Override */
	public string toString() {
		string result = mtype.toString() + " ";

		if (isActive()) {
			result += "[ACTIVE]: ";
		}
		else {
			result += "[INACTIVE]: ";
		}

		result = result + fname;
		if (this.hvar != null) {
			result += ", " + this.hvar.toString();
		}

		if (this.clangLine != null) {
			result += ", " + this.clangLine.toString();
		}

		return result;
	}

	public void deactivate() {
		active = false;
	}

	public void activate() {
		active = true;
	}

	public int getSize() {
		return size;
	}

	public void setSize(int size) {
		this.size = size;
	}

	public void toggle() {
		active = !active;
	}

	public bool isActive() {
		return active;
	}

	public bool isGlobal() {
		return isGlobal;
	}

	public bool bySymbol() {
		return bySymbol;
	}

	public void setBySymbol(bool bySymbol) {
		this.bySymbol = bySymbol;
	}

	public bool hasHighVar() {
		return this.hvar != null;
	}

	/**
	 * {@inheritDoc}
	 * 
	 * hashCode that ignores the boolean active status.
	 */
	/* @Override */
	public int hashCode() {
		int prime = 31;
		int result = 1;
		result = prime * result + mtype.hashCode();
		result = prime * result + fname.hashCode();
		if (hvar != null) {
			result = prime * result + hvar.hashCode();
		}
		return result;
	}

	/**
	 * {@inheritDoc}
	 */
	/* @Override */
	public bool equals(object o) {
		if (this == o) {
			return true;
		}
		if (o == null) {
			return false;
		}
		if (getClass() != o.GetType()) {
			return false;
		}
		TaintLabel other = (TaintLabel) o;
		if (this.mtype != other.mtype) {
			return false;
		}
		if (!this.fname.equals(other.fname)) {
			return false;
		}
		if (this.hvar != other.hvar) {
			return false;
		}
		return true;
	}

	public Address getVarnodeAddress() {
		return vnAddr;
	}

	public Varnode getVnode() {
		return vnode;
	}
